549	// sameAnswer reports whether the file already holds the answer: the same
550	// exchange under the same version and edition. The date, the notes and who
551	// recorded it do not count.
552	func sameAnswer(current, recorded nexusfixture.Fixture) bool {
553		if current.Meta.NexusVersion != recorded.Meta.NexusVersion || current.Meta.Edition != recorded.Meta.Edition {
554			return false
555		}
556		text := func(ex nexusfixture.Exchange) []byte {
557			return nexusfixture.Format(nexusfixture.Fixture{Exchanges: []nexusfixture.Exchange{ex}})
558		}
559		return bytes.Equal(text(current.Exchanges[0]), text(recorded.Exchanges[0]))
560	}
