562	var serverHeader = regexp.MustCompile(`^Nexus/(\S+) \(([A-Za-z]+)\)$`)
563	
564	// benchVersionMatches reports whether a Server header names the version and the
565	// edition of the descriptor.
566	func benchVersionMatches(server string, d Descriptor) bool {
567		m := serverHeader.FindStringSubmatch(server)
568		return m != nil && m[1] == d.NexusVersion && m[2] == d.Edition
569	}
