571	// declaresJSON reports whether a Content-Type is JSON.
572	func declaresJSON(contentType string) bool {
573		media, _, err := mime.ParseMediaType(contentType)
574		return err == nil && (media == "application/json" || strings.HasSuffix(media, "+json"))
575	}
