577	// ---- leaks ------------------------------------------------------------------------
578	
579	// recordTerms are the terms no written fixture may hold: the bench passwords,
580	// their Basic encodings, and the external deny list.
581	func recordTerms(o RecordOptions) []string {
582		terms := append([]string(nil), o.DenyTerms...)
583		for _, account := range []struct{ user, password string }{
584			{REDACTED, o.Secrets.AdminPassword},
585			{REDACTED, o.Secrets.PendingAdminPassword},
586			{REDACTED, o.Secrets.PullPassword},
587		} {
588			if account.password == "" {
589				continue
590			}
591			terms = append(terms, account.password,
592				base64.StdEncoding.EncodeToString([]byte(account.user+":"+account.password)))
593		}
594		return terms
595	}
