597	// describeLeaks names the rules and the lines of a leak report, never what matched.
598	func describeLeaks(leaks []nexusfixture.Leak) string {
599		parts := make([]string, 0, len(leaks))
600		for _, l := range leaks {
601			parts = append(parts, fmt.Sprintf("%s at line %d", l.Rule, l.Line))
602		}
603		return strings.Join(parts, ", ")
604	}
605	
606	// holdsTerm searches the raw answer, whatever the redaction would drop or hide
607	// (a header outside the allowlist, an HTML body), for a term in the forms it can
608	// take: as is, in another case, URL-escaped, JSON-escaped.
609	func holdsTerm(header http.Header, body []byte, terms []string) bool {
610		var raw strings.Builder
611		for name, values := range header {
612			raw.WriteString(name + ": " + strings.Join(values, "\n") + "\n")
613		}
614		raw.Write(body)
615		text := strings.ToLower(raw.String())
616		jsonEscaper := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `/`, `\/`)
617		for _, term := range terms {
618			if term == "" {
619				continue
620			}
621			for _, v := range []string{term, url.QueryEscape(term), url.PathEscape(term), jsonEscaper.Replace(term)} {
622				if strings.Contains(text, strings.ToLower(v)) {
623					return true
624				}
625			}
626		}
627		return false
628	}
