89	// RecordFixtures regenerates the recorded fixtures from the bench. A fixture is
90	// skipped (reported, never requested) when it says "record: skip" or holds more
91	// than one exchange. A fixture whose answer is the one it already holds, apart
92	// from its date, is left alone, bytes and modification time. Every error is a
93	// *BenchError, free of secrets; on an error nothing is written and the report is
94	// empty.
95	func RecordFixtures(ctx context.Context, o RecordOptions) (RecordReport, error) {
96		if err := ctx.Err(); err != nil {
97			return RecordReport{}, recordError("the recording was cancelled before it started", "run it again", err)
98		}
99		jobs, report, err := planRecording(o)
100		if err != nil {
101			return RecordReport{}, err
102		}
103		if len(jobs) > 0 {
104			if err := checkBenchDataset(ctx, o); err != nil {
105				return RecordReport{}, err
106			}
107		}
108		writes, unchanged, err := gatherAnswers(ctx, o, jobs)
109		if err != nil {
110			return RecordReport{}, err
111		}
112		report.Unchanged = unchanged
113		for i, w := range writes {
114			if err := writeFileAtomic(w.path, w.data, recordedFileMode, recordedDirMode); err != nil {
115				return RecordReport{}, recordError(
116					fmt.Sprintf("%s could not be written (%d fixture(s) of this run were already written)", w.name, i),
117					"check the permissions of the fixtures folder, then record again", err)
118			}
119			report.Written = append(report.Written, w.name)
120		}
121		return report, nil
122	}
123	
124	// recordError returns a BenchError; err is kept for errors.Is and errors.As and
125	// is never printed. A refusal with no underlying error keeps its own cause.
126	func recordError(cause, check string, err error) *BenchError {
127		if err == nil {
128			err = errors.New(cause)
129		}
130		return &BenchError{Kind: Unclassified, Cause: cause, Check: check, Err: err}
131	}
