242	// planFixture reads one fixture file. It returns the reason when the fixture is
243	// skipped, an error when it must not be sent.
244	func planFixture(o RecordOptions, fsys fs.FS, filePath, campaign, fileName string) (recordJob, string, error) {
245		label := campaign + "/" + strings.TrimSuffix(fileName, ".http")
246		data, err := fs.ReadFile(fsys, path.Join(campaign, fileName))
247		if err != nil {
248			return recordJob{}, "", recordError(label+" cannot be read", "check the file", err)
249		}
250		f, err := nexusfixture.Parse(campaign, fileName, data)
251		if err != nil {
252			return recordJob{}, "", recordError(label+" is not a valid fixture", "fix the file", err)
253		}
254		if reason, ok := strings.CutPrefix(f.Meta.Record, "skip"); ok {
255			return recordJob{}, strings.TrimSpace(strings.TrimPrefix(reason, ":")), nil
256		}
257		if len(f.Exchanges) != 1 {
258			return recordJob{}, fmt.Sprintf("holds %d exchanges, only one is recorded yet", len(f.Exchanges)), nil
259		}
260		// The file is scanned as it stands: a request header outside Host, the
261		// credentials and Accept, or a query other than n and last, refuses it.
262		if leaks := nexusfixture.CheckLeaks(label, data, recordTerms(o)); len(leaks) > 0 {
263			return recordJob{}, "", recordError(label+" is refused before it is sent: "+describeLeaks(leaks), "fix the file", nil)
264		}
265		ex := f.Exchanges[0]
266		if reason := refusedRequest(ex.Method, ex.Target); reason != "" {
267			return recordJob{}, "", recordError(label+" asks for something the recorder does not send ("+reason+")", "record only GET requests of the closed list of paths", nil)
268		}
269		origin, ok := o.Origins[ex.Host]
270		if !ok {
271			return recordJob{}, "", recordError(label+" is recorded on "+ex.Host+", which has no origin", "give the origin of this host:port", nil)
272		}
273		job := recordJob{campaign: campaign, name: label, path: filePath, current: f, origin: origin}
274		switch f.Identity {
275		case nexusfixture.Admin:
276			job.user, job.password = REDACTED, o.Secrets.AdminPassword
277		case nexusfixture.Pull:
278			job.user, job.password = REDACTED, o.Secrets.PullPassword
279		}
280		if job.user != "" && job.password == "" {
281			return recordJob{}, "", recordError("the bench has no stored password for "+job.user+", the account of "+label, upCheck, nil)
282		}
283		return job, "", nil
284	}
