354	// The closed list of what the recorder may ask for. A manifest or a blob read
355	// through a proxy repository would cache an image and change the bench, so none
356	// is allowed, whatever the path says.
357	var (
358		recordPaths = []*regexp.Regexp{
359			regexp.MustCompile(`^/v2/(_catalog|[a-z0-9._/-]+/tags/list)?$`),
360			regexp.MustCompile(`^/v2/[a-z0-9._-]+(/[a-z0-9._-]+)*/_catalog$`),
361			regexp.MustCompile(`^/repository/[A-Za-z0-9._-]+/v2/_catalog$`),
362			regexp.MustCompile(`^/service/rest/v1/repositories(/[A-Za-z0-9._-]+)*$`),
363		}
364		recordQueryParam = regexp.MustCompile(`^(n=[0-9]{1,6}|last=[A-Za-z0-9._/-]*)$`)
365	)
366	
367	// refusedRequest returns why a request may not be sent, or "".
368	func refusedRequest(method, target string) string {
369		p, query, hasQuery := strings.Cut(target, "?")
370		switch {
371		case method != http.MethodGet:
372			return "the method is not GET"
373		case strings.Contains(target, "..") || strings.Contains(target, "%"):
374			return "the target holds a dot-dot or an escape"
375		case strings.Contains(p+"/", "/manifests/") || strings.Contains(p+"/", "/blobs/"):
376			return "a manifest or a blob read can change the bench"
377		}
378		listed := false
379		for _, re := range recordPaths {
380			listed = listed || re.MatchString(p)
381		}
382		if !listed {
383			return "the path is not in the closed list"
384		}
385		if hasQuery {
386			for _, param := range strings.Split(query, "&") {
387				if !recordQueryParam.MatchString(param) {
388					return "the query holds more than n and last"
389				}
390			}
391		}
392		return ""
393	}
