187	// match picks the exchange recorded for the method, target and identity: the
188	// exact target first, then the catalog tolerance.
189	func match(routes []route, method, target string, id nexusfixture.Identity) (route, bool) {
190		for _, rt := range routes {
191			if rt.identity == id && rt.ex.Method == method && rt.ex.Target == target {
192				return rt, true
193			}
194		}
195		if method != http.MethodGet {
196			return route{}, false
197		}
198		return matchCatalogTolerance(routes, target, id)
199	}
200	
201	// toleratedN is the only n (what DevDesk asks) tolerated without "last".
202	const toleratedN = 1000
203	
204	// matchCatalogTolerance lets "GET P?n=1000" (no "last") be answered by a fixture
205	// recorded as "GET P" without a query, provided that answer is a 200 with no Link
206	// and lists at most 1000 names: one page holds the whole catalog, as with n=1000.
207	// Any other n is not measured and is not tolerated.
208	//
209	// Measured for the group connector: n=1000 and no n answer identically
210	// (page-group-n1000--admin and catalog-group-connector-30482--admin, pinned by
211	// TestTheCatalogToleranceHasMeasuredGround). Inferred for hosted and proxy: only
212	// no-n and n=2 were measured there. The same inference covers the catalog read by
213	// path, "/v2/<repository>/_catalog" (DEVDESK-579), on hosted and proxy: no n=1000
214	// was measured against a real Nexus on that path. A group answers 404 there, which
215	// is never tolerated, so "?n=1000" on a group path stays unmatched.
216	func matchCatalogTolerance(routes []route, target string, id nexusfixture.Identity) (route, bool) {
217		path, rawQuery, _ := strings.Cut(target, "?")
218		query, err := url.ParseQuery(rawQuery)
219		if err != nil || len(query) != 1 || len(query["n"]) != 1 {
220			return route{}, false
221		}
222		n, err := strconv.Atoi(query.Get("n"))
223		if err != nil || n != toleratedN {
224			return route{}, false
225		}
226		for _, rt := range routes {
227			ex := rt.ex
228			if rt.identity != id || ex.Method != http.MethodGet || ex.Target != path ||
229				ex.Status != http.StatusOK || ex.Header.Get("Link") != "" {
230				continue
231			}
232			var catalog struct {
233				Repositories []string `json:"repositories"`
234			}
235			if json.Unmarshal(ex.Body, &catalog) == nil && catalog.Repositories != nil && len(catalog.Repositories) <= n {
236				return rt, true
237			}
238		}
239		return route{}, false
240	}
241	
242	// rewrittenHeaders carry an address of the recorded host; they are pointed at the
243	// fake server of that host. A body is data and is never rewritten.
244	var rewrittenHeaders = []string{"Link", "Location", "Www-Authenticate"}
245	
246	// replay writes the recorded status, headers and body. Content-Length is never
247	// copied: it is recomputed from the body actually served, since a stub is shorter
248	// than the answer it summarises.
249	func (s *Server) replay(w http.ResponseWriter, rt route) {
250		s.mu.Lock()
251		s.hits[rt.fixture]++
252		rewriter := s.rewriter
253		s.mu.Unlock()
254	
255		ex := rt.ex
256		h := w.Header()
257		for name, values := range ex.Header {
258			if name == "Content-Length" {
259				continue
260			}
261			rewrite := contains(rewrittenHeaders, name)
262			for _, v := range values {
263				if rewrite {
264					v = rewriter.Replace(v)
265				}
266				h.Add(name, v)
267			}
268		}
269		if len(ex.Header.Values("Content-Type")) == 0 {
270			h["Content-Type"] = nil // a nil value stops Go from sniffing one
271		}
272		body, _ := bodyOf(ex) // a stub without a stand-in was refused by New
273		h.Set("Content-Length", strconv.Itoa(len(body)))
274		w.WriteHeader(ex.Status)
275		_, _ = w.Write(body)
276	}
277	
278	var htmlTitle = regexp.MustCompile(`, (<title>.*</title>)>$`)
279	
280	// emptyStub is the stub of a recorded empty body.
281	const emptyStub = "<empty body>"
282	
283	// bodyOf is the body to serve: the recorded one, or a stand-in for a summarised
284	// body. Only two stubs have a faithful one: an empty body and an HTML page that
285	// kept its title. valid is false for any other stub.
286	func bodyOf(ex nexusfixture.Exchange) (body []byte, valid bool) {
287		switch {
288		case ex.Stub == "":
289			return ex.Body, true
290		case ex.Stub == emptyStub:
291			return nil, true
292		case strings.HasPrefix(ex.Stub, "<HTML body omitted:"):
293			if m := htmlTitle.FindStringSubmatch(ex.Stub); m != nil {
294				return []byte("<html><head>" + m[1] + "</head></html>"), true
295			}
296		}
297		return nil, false
298	}
299	
300	func contains(list []string, s string) bool {
301		for _, v := range list {
302			if v == s {
303				return true
304			}
305		}
306		return false
307	}
